-- OpenTelemetry ClickHouse Schema
-- Supports OTLP logs, metrics, and traces as defined in opentelemetry-proto.
--
-- Produces the SAME LOGICAL table/column set as PostgreSQL-Schema.sql, adapted to
-- ClickHouse's columnar/OLAP model. The important differences from the relational
-- providers:
--
--   1. No auto-increment / RETURNING. Surrogate `id` columns are Int64 values
--      GENERATED BY THE APPLICATION (see Keryhe.Telemetry.ClickHouse):
--        - resources.id is derived deterministically from (tenant_id, resource_hash) -- the
--          table's full ORDER BY key. Deriving it from resource_hash alone gave two tenants with
--          identical resources one shared id, which leaked across tenants on read. A database
--          written before that fix must be re-created; there is no in-place migration.
--        - instrumentation_scopes.id is derived from scope_hash, which IS its whole key (scopes
--          carry no tenant and are shared across tenants by design).
--        - spans.id is derived deterministically from (trace_id, span_id).
--        - metrics.id is derived deterministically from (resource_id, scope_id, name, type).
--   2. No UNIQUE constraints / ON CONFLICT. Dedup of resources, scopes, spans, and metrics is
--      handled by ReplacingMergeTree (collapses rows sharing the ORDER BY key at merge
--      time), backed by an in-process cache + per-batch dedup on the write side.
--   3. No foreign keys / cascades. Referential integrity is a write-path convention;
--      deletes remove child rows explicitly (see ClickHouseWriteStore).
--   4. Attributes are stored as String (JSON text) columns named *_json, matching how the
--      shared Dapper read repositories deserialize them in C#.
--   5. Timestamps *_unix_nano are Int64 (nanoseconds since epoch), as elsewhere.
--
-- Usage:
--   clickhouse-client --database telemetry --multiquery < ClickHouse-Schema.sql
--   (or:  schema/apply-schema.sh clickhouse telemetry)

-- =============================================================================
-- COMMON / MULTI-TENANT TABLES
-- =============================================================================

CREATE TABLE IF NOT EXISTS tenants
(
    id         Int64,
    name       String,
    created_at DateTime64(9) DEFAULT now64(9)
)
ENGINE = ReplacingMergeTree
ORDER BY id;

CREATE TABLE IF NOT EXISTS api_keys
(
    id           Int64,
    tenant_id    Int64,
    key_hash     String,
    name         String,
    is_active    UInt8 DEFAULT 1,
    created_at   DateTime64(9) DEFAULT now64(9),
    last_used_at Nullable(DateTime64(9))
)
ENGINE = ReplacingMergeTree
ORDER BY key_hash;

-- Resource: the entity producing telemetry. id = deterministic hash of (tenant_id, resource_hash),
-- matching the ORDER BY below. Both parts are required: the hash covers only schema_url +
-- attributes, so two tenants running the same service produce the same hash.
CREATE TABLE IF NOT EXISTS resources
(
    id              Int64,
    tenant_id       Int64,
    resource_hash   String,
    schema_url      Nullable(String),
    created_at      DateTime64(9) DEFAULT now64(9),
    attributes_json Nullable(String)
)
ENGINE = ReplacingMergeTree
ORDER BY (tenant_id, resource_hash);

-- Instrumentation scope (library). id = deterministic hash of scope_hash.
CREATE TABLE IF NOT EXISTS instrumentation_scopes
(
    id              Int64,
    name            String,
    version         Nullable(String),
    schema_url      Nullable(String),
    scope_hash      String,
    created_at      DateTime64(9) DEFAULT now64(9),
    attributes_json Nullable(String)
)
ENGINE = ReplacingMergeTree
ORDER BY scope_hash;

-- =============================================================================
-- TRACES
-- =============================================================================

-- Spans. Dedup key is (trace_id, span_id); id is derived from that pair.
CREATE TABLE IF NOT EXISTS spans
(
    id                       Int64,
    trace_id                 String,
    span_id                  String,
    parent_span_id           Nullable(String),
    resource_id              Int64,
    scope_id                 Int64,
    name                     String,
    kind                     String DEFAULT 'UNSPECIFIED',
    start_time_unix_nano     Int64,
    end_time_unix_nano       Int64,
    dropped_attributes_count Int32 DEFAULT 0,
    dropped_events_count     Int32 DEFAULT 0,
    dropped_links_count      Int32 DEFAULT 0,
    trace_state              Nullable(String),
    flags                    Int32 DEFAULT 0,
    status_code              String DEFAULT 'UNSET',
    status_message           Nullable(String),
    created_at               DateTime64(9) DEFAULT now64(9),
    attributes_json          Nullable(String),
    events_json              Nullable(String),
    links_json               Nullable(String)
)
ENGINE = ReplacingMergeTree
PARTITION BY toYYYYMMDD(fromUnixTimestamp64Nano(start_time_unix_nano))
ORDER BY (trace_id, span_id);

-- schema 2.12.0 adds idx_spans_error (a status_code-filtered index on start_time_unix_nano) to
-- the other four providers, for mode=errors. Not needed here: the daily partition plus this
-- table's own ORDER BY (trace_id, span_id) already lets a status_code='ERROR' scan skip whole
-- partitions/granules outside the query's time bounds without a dedicated index.

-- span_events and span_links were dropped in 2.11.0: neither was ever read or written
-- independently of its parent span, so both collapsed into spans.events_json/links_json.

-- =============================================================================
-- METRICS
-- =============================================================================

CREATE TABLE IF NOT EXISTS metrics
(
    id          Int64,
    resource_id Int64,
    scope_id    Int64,
    name        String,
    description Nullable(String),
    unit        Nullable(String),
    type        String,
    created_at  DateTime64(9) DEFAULT now64(9)
)
-- Metric identity, the ClickHouse analogue of the relational uk_metric_identity UNIQUE.
-- ORDER BY must equal the dedup key exactly and contain nothing else:
--   * `id` is a pure function of the key, so it adds no selectivity -- and including it is
--     precisely why the previous `MergeTree ORDER BY (name, id)` never collapsed anything,
--     since id was a fresh RowId.Next() on every export.
--   * `created_at` must never be added: it varies per insert and would defeat the collapse.
--
-- `name` no longer leads the sort key. That is fine here: dedup takes this table to tens of
-- rows, which is a single 8192-row granule, so every lookup reads the same granule whatever
-- the key order -- and the high-volume reads join on metric_id rather than scanning by name.
--
-- Dedup is EVENTUAL (merge time). The write-side cache reduces inserts to one per metric per
-- process lifetime, so duplicates are only visible in the window just after a restart.
ENGINE = ReplacingMergeTree
ORDER BY (resource_id, scope_id, name, type);

-- exemplars_json (2.9.0) replaces the former single exemplar_id column and the shared
-- `exemplars` table, which no writer ever populated. OTLP declares `repeated Exemplar
-- exemplars` on every data point except Summary, so one id per row could never hold more than
-- the first. The list is stored as JSON on the data point itself: a child table would need each
-- data point's generated id, which the bulk-load path (binary COPY / bulk copy) does not hand
-- back, and JSON is already how bucket_counts, explicit_bounds and quantile_values are stored.
-- Trade-off: an exemplar's trace_id is no longer indexable. No read path queries it.
CREATE TABLE IF NOT EXISTS gauge_data_points
(
    id                   Int64 DEFAULT 0,
    metric_id            Int64,
    start_time_unix_nano Nullable(Int64),
    time_unix_nano       Int64,
    value_double         Nullable(Float64),
    value_int            Nullable(Int64),
    flags                Int32 DEFAULT 0,
    attributes_json      Nullable(String),
    exemplars_json       Nullable(String)
)
ENGINE = MergeTree
PARTITION BY toYYYYMMDD(fromUnixTimestamp64Nano(time_unix_nano))
ORDER BY (metric_id, time_unix_nano);

CREATE TABLE IF NOT EXISTS sum_data_points
(
    id                      Int64 DEFAULT 0,
    metric_id               Int64,
    start_time_unix_nano    Nullable(Int64),
    time_unix_nano          Int64,
    value_double            Nullable(Float64),
    value_int               Nullable(Int64),
    aggregation_temporality String DEFAULT 'UNSPECIFIED',
    is_monotonic            UInt8 DEFAULT 0,
    flags                   Int32 DEFAULT 0,
    attributes_json         Nullable(String),
    exemplars_json          Nullable(String)
)
ENGINE = MergeTree
PARTITION BY toYYYYMMDD(fromUnixTimestamp64Nano(time_unix_nano))
ORDER BY (metric_id, time_unix_nano);

CREATE TABLE IF NOT EXISTS histogram_data_points
(
    id                      Int64 DEFAULT 0,
    metric_id               Int64,
    start_time_unix_nano    Nullable(Int64),
    time_unix_nano          Int64,
    count                   Int64,
    sum_value               Nullable(Float64),
    bucket_counts           Nullable(String),
    explicit_bounds         Nullable(String),
    aggregation_temporality String DEFAULT 'UNSPECIFIED',
    flags                   Int32 DEFAULT 0,
    min_value               Nullable(Float64),
    max_value               Nullable(Float64),
    attributes_json         Nullable(String),
    exemplars_json          Nullable(String)
)
ENGINE = MergeTree
PARTITION BY toYYYYMMDD(fromUnixTimestamp64Nano(time_unix_nano))
ORDER BY (metric_id, time_unix_nano);

CREATE TABLE IF NOT EXISTS exponential_histogram_data_points
(
    id                      Int64 DEFAULT 0,
    metric_id               Int64,
    start_time_unix_nano    Nullable(Int64),
    time_unix_nano          Int64,
    count                   Int64,
    sum_value               Nullable(Float64),
    scale                   Int32,
    zero_count              Int64,
    positive_offset         Nullable(Int32),
    positive_bucket_counts  Nullable(String),
    negative_offset         Nullable(Int32),
    negative_bucket_counts  Nullable(String),
    aggregation_temporality String DEFAULT 'UNSPECIFIED',
    flags                   Int32 DEFAULT 0,
    min_value               Nullable(Float64),
    max_value               Nullable(Float64),
    attributes_json         Nullable(String),
    exemplars_json          Nullable(String)
)
ENGINE = MergeTree
PARTITION BY toYYYYMMDD(fromUnixTimestamp64Nano(time_unix_nano))
ORDER BY (metric_id, time_unix_nano);

CREATE TABLE IF NOT EXISTS summary_data_points
(
    id                   Int64 DEFAULT 0,
    metric_id            Int64,
    start_time_unix_nano Nullable(Int64),
    time_unix_nano       Int64,
    count                Int64,
    sum_value            Float64,
    quantile_values      Nullable(String),
    flags                Int32 DEFAULT 0,
    attributes_json      Nullable(String)
)
ENGINE = MergeTree
PARTITION BY toYYYYMMDD(fromUnixTimestamp64Nano(time_unix_nano))
ORDER BY (metric_id, time_unix_nano);

-- =============================================================================
-- LOGS
-- =============================================================================

CREATE TABLE IF NOT EXISTS log_records
(
    id                       Int64 DEFAULT 0,
    resource_id              Int64,
    scope_id                 Int64,
    time_unix_nano           Int64 DEFAULT 0,
    observed_time_unix_nano  Nullable(Int64),
    severity_number          Nullable(Int32),
    severity_text            Nullable(String),
    event_name               Nullable(String),
    body_type                Nullable(String),
    body_value               Nullable(String),
    dropped_attributes_count Int32 DEFAULT 0,
    flags                    Int32 DEFAULT 0,
    trace_id                 Nullable(String),
    span_id                  Nullable(String),
    created_at               DateTime64(9) DEFAULT now64(9),
    attributes_json          Nullable(String)
)
ENGINE = MergeTree
PARTITION BY toYYYYMMDD(fromUnixTimestamp64Nano(time_unix_nano))
ORDER BY (time_unix_nano, resource_id);

-- =============================================================================
-- ALERTING
-- =============================================================================

CREATE TABLE IF NOT EXISTS alert_rules
(
    id               Int32,
    tenant_id        Int64,
    name             String,
    type             String,
    service_name     Nullable(String),
    condition_json   String,
    webhook_url      String,
    cooldown_minutes Int32 DEFAULT 60,
    enabled          UInt8 DEFAULT 1,
    created_at       DateTime64(9) DEFAULT now64(9),
    last_fired_at    Nullable(DateTime64(9))
)
ENGINE = ReplacingMergeTree
ORDER BY id;

CREATE TABLE IF NOT EXISTS alert_events
(
    id           Int64,
    rule_id      Int32,
    fired_at     DateTime64(9) DEFAULT now64(9),
    details_json String
)
ENGINE = MergeTree
ORDER BY (rule_id, id);

-- =============================================================================
-- RETENTION
-- =============================================================================

-- Single global row (id always 1) — see IRetentionSettingsRepository for why this is
-- untenanted. ReplacingMergeTree so ClickHouseRetentionSettingsRepository's
-- ALTER TABLE ... UPDATE mutation (see its "control-plane is best-effort" notes, same
-- pattern as alert_rules) collapses to one row at merge time, matching the alert_rules
-- dedup strategy.
CREATE TABLE IF NOT EXISTS retention_settings
(
    id                    Int8 DEFAULT 1,
    trace_retention_days  Int32,
    log_retention_days    Int32,
    metric_retention_days Int32,
    updated_at            DateTime64(9) DEFAULT now64(9)
)
ENGINE = ReplacingMergeTree
ORDER BY id;

-- =============================================================================
-- UTILITY
-- =============================================================================

CREATE TABLE IF NOT EXISTS schema_version
(
    version    String,
    applied_at DateTime64(9) DEFAULT now64(9)
)
ENGINE = ReplacingMergeTree
ORDER BY version;
-- NOTE: the schema_version row is seeded at the very END of this script (after all
-- tables and views), so a partial/failed apply never records a version that the
-- apply-schema.sh version gate would wrongly treat as "already applied".

-- =============================================================================
-- VIEWS (parity with the relational providers; not on the hot read path — the
-- read repositories build their own SQL and extract service.name in C#).
-- JSON access uses ClickHouse's JSONExtractString.
-- =============================================================================

CREATE VIEW IF NOT EXISTS trace_summary AS
SELECT
    s.trace_id                                              AS trace_id_hex,
    s.trace_id                                              AS trace_id,
    count()                                                 AS span_count,
    min(s.start_time_unix_nano)                             AS trace_start_time,
    max(s.end_time_unix_nano)                               AS trace_end_time,
    max(s.end_time_unix_nano) - min(s.start_time_unix_nano) AS trace_duration_ns,
    any(r.id)                                               AS resource_id
FROM spans s
INNER JOIN resources r ON s.resource_id = r.id
GROUP BY s.trace_id;

CREATE VIEW IF NOT EXISTS service_map AS
SELECT
    JSONExtractString(assumeNotNull(parent_res.attributes_json), 'service.name') AS parent_service,
    JSONExtractString(assumeNotNull(child_res.attributes_json),  'service.name') AS child_service,
    child.kind                                                                   AS span_kind,
    count()                                                                      AS call_count
FROM spans child
INNER JOIN spans parent
    ON child.parent_span_id = parent.span_id AND child.trace_id = parent.trace_id
INNER JOIN resources parent_res ON parent.resource_id = parent_res.id
INNER JOIN resources child_res  ON child.resource_id  = child_res.id
WHERE parent_service != '' AND child_service != '' AND parent_service != child_service
GROUP BY parent_service, child_service, child.kind;

CREATE VIEW IF NOT EXISTS service_map_detailed AS
SELECT
    JSONExtractString(assumeNotNull(parent_res.attributes_json), 'service.name') AS parent_service,
    JSONExtractString(assumeNotNull(child_res.attributes_json),  'service.name') AS child_service,
    child.kind                                                                   AS span_kind,
    count()                                                                      AS call_count,
    avg(child.end_time_unix_nano - child.start_time_unix_nano) / 1000000         AS avg_duration_ms,
    min(child.end_time_unix_nano - child.start_time_unix_nano) / 1000000         AS min_duration_ms,
    max(child.end_time_unix_nano - child.start_time_unix_nano) / 1000000         AS max_duration_ms,
    countIf(child.status_code = 'ERROR')                                         AS error_count,
    (countIf(child.status_code = 'ERROR') / count()) * 100                       AS error_rate
FROM spans child
INNER JOIN spans parent
    ON child.parent_span_id = parent.span_id AND child.trace_id = parent.trace_id
INNER JOIN resources parent_res ON parent.resource_id = parent_res.id
INNER JOIN resources child_res  ON child.resource_id  = child_res.id
WHERE parent_service != '' AND child_service != '' AND parent_service != child_service
GROUP BY parent_service, child_service, child.kind;

CREATE VIEW IF NOT EXISTS log_severity_stats AS
SELECT
    severity_text,
    severity_number,
    count()                                              AS count,
    toDate(fromUnixTimestamp64Nano(time_unix_nano))      AS log_date
FROM log_records
WHERE time_unix_nano > 0
GROUP BY severity_text, severity_number, log_date;

-- Seeded with today's implicit defaults (traces 90d, logs 90d, metrics 180d).
INSERT INTO retention_settings (id, trace_retention_days, log_retention_days, metric_retention_days)
VALUES (1, 90, 90, 180);

-- =============================================================================
-- SCHEMA VERSION (recorded LAST)
-- =============================================================================
-- Only inserted when every statement above succeeded, so a partial apply cannot
-- leave a false version marker for the apply-schema.sh gate.
-- 2.12.0 is a no-op bump for ClickHouse alone, like 2.8.0 before it: the other four providers add
-- idx_spans_error (a status_code-filtered index) for mode=errors, but spans' ORDER BY (trace_id,
-- span_id) with a daily partition already gives ClickHouse the equivalent skip behavior — see the
-- comment on the spans table above.
-- 2.11.0 drops span_events and span_links, folding both into spans.events_json/links_json --
-- which also removes the retried-flush double-insert risk those two MergeTree tables carried,
-- since there is nothing left to insert alongside the ReplacingMergeTree-deduped spans row.
-- 2.10.0 adds retention_settings, backing the application-level RetentionWorker
-- (Keryhe.Telemetry.Api) that is now the one retention mechanism across all five providers.
-- 2.9.0 changes the metric data-point tables here exactly as it does everywhere else:
-- exemplar_id out, exemplars_json in. 2.8.0 before it was a no-op bump for ClickHouse alone --
-- spans' ORDER BY (trace_id, span_id) with a daily partition already gave it what the relational
-- providers got from the four indexes they dropped (see PostgreSQL-Schema.sql), and it has no
-- GIN-style JSONB index to carry the equivalent write cost of.
INSERT INTO schema_version (version) VALUES ('2.12.0');
